entries.body:
digraph bread_family {
  rankdir=LR;
  bgcolor="#faf6ee";
  node [shape=box, style="rounded,filled", fontname="Helvetica", fontsize=11, color="#a04a2d", fillcolor="#fff", fontcolor="#3a2517"];
  edge [color="#a04a2d", arrowsize=0.7];

  starter [label="Sourdough\nstarter", fillcolor="#f4e8d0"];
  brioche_dough [label="Brioche\ndough", fillcolor="#f4e8d0"];
  whole_wheat [label="Whole-wheat\nbase", fillcolor="#f4e8d0"];

  country [label="Country sourdough"];
  rye [label="Sourdough rye"];
  boule [label="Sourdough boule"];
  seeded [label="Seeded country"];
  brioche_loaf [label="Brioche loaf"];
  burger_buns [label="Burger buns"];
  morning_buns [label="Cardamom\nmorning buns"];
  whole_loaf [label="Whole-wheat loaf"];

  starter -> country;
  starter -> rye;
  starter -> boule;
  starter -> seeded;
  brioche_dough -> brioche_loaf;
  brioche_dough -> burger_buns;
  brioche_dough -> morning_buns;
  whole_wheat -> whole_loaf;
}

{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "title": {"text": "Loaves sold · week of May 13", "fontSize": 14, "font": "Iowan Old Style, Georgia, serif", "color": "#3a2517"},
  "width": 380,
  "height": 220,
  "background": "#faf6ee",
  "padding": 16,
  "data": {
    "values": [
      {"product": "Cardamom buns",  "sold": 168},
      {"product": "Country sourdough", "sold": 142},
      {"product": "Burger buns",   "sold": 92},
      {"product": "Brioche loaf",   "sold": 86},
      {"product": "Whole wheat",    "sold": 78},
      {"product": "Sourdough rye",  "sold": 64},
      {"product": "Seeded country", "sold": 54}
    ]
  },
  "mark": {"type": "bar", "color": "#a04a2d", "cornerRadiusEnd": 3},
  "encoding": {
    "x": {"field": "product", "type": "nominal", "axis": {"labelAngle": -32, "labelColor": "#3a2517", "titleColor": "#3a2517"}, "sort": "-y", "title": null},
    "y": {"field": "sold", "type": "quantitative", "title": "Units sold", "axis": {"labelColor": "#3a2517", "titleColor": "#3a2517", "grid": true, "gridColor": "#e8dec9"}}
  }
}
